join public.card_definitions d on d.code = k.code
on conflict (definition_id) do nothing;

do $$
begin
  if (select count(*) from public.card_definitions d join public.combat_kits k on k.definition_id = d.id
      where d.code in ('P097', 'P100', 'P122', 'P170', 'P220', 'P030', 'P031', 'P050', 'P073', 'P127', 'P159', 'P205', 'P218', 'P028', 'P033', 'P051', 'P166', 'P222', 'P223', 'P025', 'P045', 'P052', 'P053', 'P090', 'P115')) <> 25 then
    raise exception 'a character of the fifth batch has no kit';
  end if;
end $$;
